const test = require('node:test');
const assert = require('node:assert/strict');
const { originLabel } = require('../src/origin-label.cjs');

test("network origins include only nondefault ports", () => {
  assert.equal(originLabel('https://portal.spruce.example:443/path?q=1#x'), 'https://portal.spruce.example');
  assert.equal(originLabel('http://portal.spruce.example:80/path'), 'http://portal.spruce.example');
  assert.equal(originLabel('https://portal.spruce.example:8443/path'), 'https://portal.spruce.example:8443');
});

test("blob origins are inherited and opaque origins are strings", () => {
  assert.equal(originLabel('blob:https://portal.spruce.example:443/c73f'), 'https://portal.spruce.example');
  assert.equal(originLabel('data:text/plain,spruce'), 'null');
  assert.equal(typeof originLabel('mailto:ops@spruce.example'), 'string');
  assert.equal(originLabel('mailto:ops@spruce.example'), 'null');
});

